import { Component } from './base/Component';
import { ensureElement, createElement } from '../utils/utils';
// Класс корзины с товарами
export class Basket extends Component {
    constructor(container, events) {
        super(container);
        this.events = events;
        this._list = ensureElement('.basket__list', this.container);
        this._total = container.querySelector('.basket__price');
        this._button = this.container.querySelector('.basket__button');
        if (this._button) {
            this._button.addEventListener('click', () => {
                events.emit('order:open');
            });
        }
        this.items = [];
    }
    // Задает состояние кнопки
    statusButton(state) {
        this.setDisable(this._button, state);
    }
    // Устанавливает товары в корзине
    set items(items) {
        if (items.length) {
            this._list.replaceChildren(...items);
            this.statusButton(false);
        }
        else {
            this._list.replaceChildren(createElement('p', {
                textContent: 'Корзина пуста',
            }));
            this.statusButton(true);
        }
    }
    // Устанавливает общую сумму товаров в корзине
    set total(total) {
        this.setText(this._total, `${total} синапсов`);
    }
}
