import { Api } from "./base/api";
// Класс для работы с конкретным сервером
export class ApiWebLarek extends Api {
    constructor(cdn, baseUrl, options) {
        super(baseUrl, options);
        this.cdn = cdn;
    }
    // Получение списка продуктов с сервера
    getListProducts() {
        return this.get('/product').then((data) => data.items.map((item) => (Object.assign(Object.assign({}, item), { image: this.cdn + item.image }))));
    }
    // Получение продукта с сервера по запросу id
    getProduct(id) {
        return this.get(`/product/${id}`)
            .then((item) => (Object.assign(Object.assign({}, item), { image: this.cdn + item.image.replace('.svg', '.png') })));
    }
    // Передача успешного заказа на сервер и возвращение результата
    createOrder(order) {
        return this.post(`/order`, order).then((data) => data);
    }
}
