import { Component } from './base/Component';
import { ensureElement } from '../utils/utils';
// Класс cподтверждения успешного заказа продуктов
export class SuccessOrder extends Component {
    constructor(container, events) {
        super(container);
        this.events = events;
        this._amount = ensureElement('.order-success__description', this.container);
        this._close = ensureElement('.order-success__close', this.container);
        this._close.addEventListener('click', () => {
            this.events.emit('order:finished');
        });
    }
    // Устанавливает сумму успешного заказа
    set totalOrder(total) {
        this.setText(this._amount, `Списано ${total} синапсов`);
    }
}
