import { ensureElement } from "../utils/utils";
import { FormOrder } from "./FormOrder";
// Класс оплаты и адреса доставки заказа
export class FormAddress extends FormOrder {
    constructor(container, events) {
        super(container, events);
        this._paymentContainer = ensureElement('.order__buttons', this.container);
        this._paymentButtons = Array.from(this._paymentContainer.querySelectorAll('.button_alt'));
        this._address = ensureElement('.form__input[name="address"]', this.container);
        this._paymentContainer.addEventListener('click', (e) => {
            const target = e.target;
            if (!target.classList.contains('button_alt'))
                return;
            this.selectPayment = target.name;
            events.emit(`order-payment:change`, { target: target.name });
        });
    }
    // Устанавливает способ оплаты заказа
    set selectPayment(metodPay) {
        this._paymentButtons.forEach(button => {
            this.toggleClass(button, 'button_alt-active', button.name === metodPay);
        });
    }
    // Устанавливает адрес доставки товара
    set address(value) {
        this._address.value = value;
    }
}
