import { Component } from './base/Component';
import { ensureElement } from '../utils/utils';
// Класс модального окна
export class Modal extends Component {
    constructor(container, events) {
        super(container);
        this.events = events;
        this._content = ensureElement('.modal__content', this.container);
        this._closeButton = ensureElement('.modal__close', this.container);
        this._closeButton.addEventListener('click', this.close.bind(this));
        this.container.addEventListener('click', this.close.bind(this));
        this._content.addEventListener('click', (event) => event.stopPropagation());
        document.addEventListener('keydown', (e) => {
            if (e.key === 'Escape')
                this.close();
        });
    }
    // Устанавливает контент для модалього окна
    set content(value) {
        this._content.replaceChildren(value);
    }
    // Открывает модальное окно
    open() {
        this.container.classList.add('modal_active');
        this.events.emit('modal:open');
        document.body.style.overflow = 'hidden';
    }
    // Cкрывает модальное окно
    close() {
        this.container.classList.remove('modal_active');
        this._content.replaceChildren();
        this.events.emit('modal:close');
        document.body.style.overflow = '';
    }
    // Создает и открывает модальное окно по переданным данным
    render(data) {
        super.render(data);
        this.open();
        return this.container;
    }
}
